  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    dist = {}
    for a,b,d in dist_list:
        if a < b:
            dist[(a,b)] = d
        else:
            dist[(b,a)] = d
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i+1, n):
            u = nodes[i]
            v = nodes[j]
            pair = (u,v) if u < v else (v,u)
            d = dist.get(pair)
            if d is None:
                raise ValueError('missing distance')
            w = max(core[u], core[v], d)
            edges.append((w, u, v))
    edges.sort()
    parent = {node: node for node in nodes}
    size = {node: 1 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]
        return True
    mst = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst.append([u, v, w])
            total += w
            if len(mst) == n - 1:
                break
    if len(mst) != n - 1:
        raise ValueError('disconnected')
    return {'mst_edges': mst, 'total_weight': total}
